const item = $input.first().json.result.item;
const file = item.ufCrmQuoteQuotationDocx;
const fileObj = Array.isArray(file) ? file[0] : file;
const url = fileObj.urlMachine || fileObj.url || fileObj.downloadUrl;
return [{ json: { itemId: item.id, fileUrl: url, stageId: item.stageId } }];

const inp = $input.first();
const headers = inp.json?.headers || {};
let contentType = (headers['content-type'] || headers['Content-Type'] || '').toLowerCase();
let disposition = headers['content-disposition'] || headers['Content-Disposition'] || '';
let fileName = 'file';
const m = disposition.match(/filename\*?=(?:UTF-8'')?"?([^";]+)"?/i);
if (m) fileName = decodeURIComponent(m[1]);
let format = 'other';
let mimeType = 'application/octet-stream';
if (contentType.startsWith('image/')) {
  format = 'image';
  mimeType = contentType.split(';')[0];
} else if (contentType.includes('pdf')) {
  format = 'pdf';
  mimeType = 'application/pdf';
} else if (contentType.includes('wordprocessingml') || contentType.includes('msword') || fileName.toLowerCase().endsWith('.docx') || fileName.toLowerCase().endsWith('.doc')) {
  format = 'docx';
  mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
} else {
  const bin = inp.binary?.data;
  if (bin && bin.data) {
    const first4 = Buffer.from(bin.data, 'base64').slice(0, 4).toString('hex');
    if (first4.startsWith('89504e47')) { format = 'image'; mimeType = 'image/png'; }
    else if (first4.startsWith('ffd8ff')) { format = 'image'; mimeType = 'image/jpeg'; }
    else if (first4.startsWith('25504446')) { format = 'pdf'; mimeType = 'application/pdf'; }
    else if (first4.startsWith('504b0304')) { format = 'docx'; mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'; }
  }
}
const itemId = $('Extract File URL').first().json.itemId;
return [{ json: { itemId, format, mimeType, fileName }, binary: inp.binary }];

const inp = $input.first();
const binary = inp.binary?.data;
if (!binary) throw new Error('Missing binary data in Build AI Content');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buffer.toString('base64');
const detected = $('Detect Format').first().json;
const { itemId, format, fileName } = detected;
let contentPart;
if (format === 'image') {
  contentPart = { type: 'image_url', image_url: { url: `data:${detected.mimeType};base64,${b64}`, detail: 'high' } };
} else {
  const cleanName = (fileName || 'quotation').replace(/\.(docx|doc)$/i, '.pdf');
  contentPart = { type: 'file', file: { filename: cleanName.endsWith('.pdf') ? cleanName : cleanName + '.pdf', file_data: `data:application/pdf;base64,${b64}` } };
}
const systemPrompt = "You extract tent quotation data. CRITICAL RULES: (1) Find EVERY line item in ALL pricing tables — do not stop after the first row. A quotation typically has 2-5 line items (main product, awnings, transportation, installation, accessories). (2) A single document may contain MULTIPLE separate quotations — extract each as its own object in the quotations array. Look for section breaks, separate quotation numbers, or 'Quotation 1 / Quotation 2' markers. (3) Output ONLY valid JSON, no markdown. Missing text → empty string; missing numbers → 0. Currency values as plain numbers (no RM/comma). Dates as YYYY-MM-DD.";
const taxonomy = `Reference taxonomy — output the exact string from this list when applicable, otherwise output the quotation's text as-is:
- width: 3m, 6m, 9m, 15m, 19m, 20m, 25m, 30m, 40m, 50m, 60m
- length: 5m, 10m, 15m, 20m, 25m, 30m, 35m, 40m, 45m, 50m, Continous +5m
- profile: 80mm x 60mm (CM), 98mm x 60mm, 155mm x 60mm, 158mm x 60mm, 158mm x 89mm (CM), 210mm x 112mm, 255mm x 120mm, 300mm x 125mm, 350mm x 125mm
- canvas_material: BO1100-HSH850, BO1100-SX800, TPT-HSB080
- colour: White, Grey, Grey White, Blue Grey, Red Grey, Clear
- structure: Temporary, Semi - Permanent, Temporary (CM), Semi - Permanent (CM)
- corner_type: T1 - Fitting, T2 - Side Plate, T3 - Side Plate
- side_support_type: Side Cable, Side Support Beam, Cross Support Frame, 2D Truss
- qty_side_support: 1 Bay, 2 Bay, 3 Bay, More
- ground_anchoring: Spike, Wall Plug, Chemical Bolt, J - Bolt, Concreate Footing, Counter Weight (Concreate Block), Counter Weight (Connection Plate)
- roof_canvas: Standard Cutting, CM Cutting, C/W Separate Canvas Flap, C/W Overlap Canvas Flap
- sidewall: QTY Pcs, No
- sidewall_option: Canvas sidewall c/w liners wall hook & zipper, Canvas sidewall c/w liners wall hook & rope with eylet, Canvas sidewall c/w 1 french window, Canvas sidewall c/w 2 french window, Canvas sidewall c/w 3 side liner (CM), Hard Panel Sidewall complete set, Glass panel sidewall complete set
- gable_end_canvas: 1 pcs, 2 pcs, No
- gable_end_canvas_details: Std Cutting, Printing Cutting, C/W Window, C/W Tensioning Cable, C/W Tensioning Complete Set
- gable_end_structure: 1 Set, 2 Set, No
- gutter: Canvas Gutter c/w wall hook, PVC Gutter c/w hook bracket, Zinc Gutter c/w pvc down pipe (CM), No
- door: Double Door, Single Door, Super Double Door, Super Single Door, Roller Shutter, Industrial Sliding Door, Motorize Shutter Door
- accessories: Roof Underlay, Gable End Underlay, Sidewall Underlay, Alumunium Foil, 50 Inch Industrial Ventilation Fan, Highbay LED c/w Wiring`;
const userText = `Extract quotation data as JSON. CRITICAL: (a) look at EVERY row in the pricing table and include ALL line items; (b) if the document has multiple quotations (separate quotation numbers/sections), each is its own object in the quotations array.

${taxonomy}

Product family guidance: 'product_family' is the base product name for grouping SKU variants across quotations (e.g. 'Aluminium Free Span Structure'). 'product_variant_name' is the full descriptive name from the quotation. For non-tent lines like 'Awning c/w column', 'Transportation', 'Installation' — use closest generic family. Quantity: numeric quantity from the quotation table (default 1). Unit measure: 'block', 'set', 'job', 'pcs' as shown in the quotation table (default 'pcs').

Schema:
{
  "quotations": [
    {
      "quotation_ref": string,
      "quotation_date": string (YYYY-MM-DD),
      "grand_total_rm": number,
      "line_items": [
        {
          "line_no": number,
          "product_family": string,
          "product_variant_name": string,
          "unit_price_rm": number,
          "line_total_rm": number,
          "quantity": number,
          "unit_measure": string,
          "specs": {
            "width": string, "length": string, "frame": string, "profile": string,
            "canvas_material": string, "colour": string, "structure": string,
            "corner_type": string, "side_support_type": string, "qty_side_support": string,
            "ground_anchoring": string, "roof_canvas": string, "sidewall": string,
            "sidewall_option": string, "gable_end_canvas": string,
            "gable_end_canvas_details": string, "gable_end_structure": string,
            "gutter": string, "door": string, "door_qty": string, "accessories": string
          }
        }
      ]
    }
  ]
}`;
const aiBody = {
  model: 'gpt-5.5',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: [ { type: 'text', text: userText }, contentPart ] }
  ],
  max_completion_tokens: 16000,
  response_format: { type: 'json_object' }
};
return [{ json: { itemId, format, fileName, aiBody } }];

// v4 — 1 line item = 1 Quote record. Migrate SPA 1038 → Quote entity (7). Enum mapping.
const BASE = $env.BITRIX_TFSSB_URL;
const QUOTE_ENTITY_TYPE_ID = 7;
const PRODUCTROW_OWNER_TYPE = 'Q'; // Quote SYMBOL_CODE_SHORT
const PROP_PARENT_LINK = 46;
const PROP_CATALOG = {
  WIDTH:100, LENGTH:102, FRAME:104, PROFILE:106, CANVAS_MATERIAL:108, COLOUR:110,
  STRUCTURE:112, CORNER_TYPE:114, SIDE_SUPPORT_TYPE:116, QTY_SIDE_SUPPORT:118,
  GROUND_ANCHORING:120, ROOF_CANVAS:122, SIDEWALL:124, SIDEWALL_OPTION:126,
  GABLE_END_CANVAS:128, GABLE_END_CANVAS_DETAILS:130, GABLE_END_STRUCTURE:132,
  GUTTER:134, DOOR:136, DOOR_QTY:138, ACCESSORIES:140, QUOTATION_REF:142
};
// Enum value ID map for Quote fields — populated from userfieldconfig 2026-08-28
const ENUM_MAP = {
  ufCrmQuoteWidth: {'3m':'196','6m':'198','9m':'200','15m':'202','19m':'204','20m':'206','25m':'208','30m':'210','40m':'212','50m':'214','60m':'216'},
  ufCrmQuoteLength: {'5m':'218','10m':'220','15m':'222','20m':'224','25m':'226','30m':'228','35m':'230','40m':'232','45m':'234','50m':'236','Continous +5m':'238'},
  ufCrmQuoteProfile: {'80mm x 60mm (CM)':'240','98mm x 60mm':'242','155mm x 60mm':'244','158mm x 60mm':'246','158mm x 89mm (CM)':'248','210mm x 112mm':'250','255mm x 120mm':'252','300mm x 125mm':'254','350mm x 125mm':'256'},
  ufCrmQuoteCanvasMaterial: {'BO1100-HSH850':'258','BO1100-SX800':'260','TPT-HSB080':'262'},
  ufCrmQuoteColour: {'White':'264','Grey':'266','Grey White':'268','Blue Grey':'270','Red Grey':'272','Clear':'274'},
  ufCrmQuoteStructure: {'Temporary':'276','Semi - Permanent':'278','Temporary (CM)':'280','Semi - Permanent (CM)':'282'},
  ufCrmQuoteCornerType: {'T1 - Fitting':'284','T2 - Side Plate':'286','T3 - Side Plate':'288'},
  ufCrmQuoteSideSupportType: {'Side Cable':'290','Side Support Beam':'292','Cross Support Frame':'294','2D Truss':'296'},
  ufCrmQuoteQtySideSupports: {'1 Bay':'298','2 Bay':'300','3 Bay':'302','More':'304'},
  ufCrmQuoteGroundAchoring: {'Spike':'306','Wall Plug':'308','Chemical Bolt':'310','J - Bolt':'312','Concreate Footing':'314','Counter Weight (Concreate Block)':'316','Counter Weight (Connection Plate)':'318'},
  ufCrmQuoteRoofCanvas: {'Standard Cutting':'320','CM Cutting':'322','C/W Separate Canvas Flap':'324','C/W Overlap Canvas Flap':'326'},
  ufCrmQuoteSidewall: {'QTY Pcs':'328','No':'330'},
  ufCrmQuoteSidewallOption: {'Canvas sidewall c/w liners, wall hook & zipper':'332','Canvas sidewall c/w liners, wall hook & rope with eylet':'334','Canvas sidewall c/w 1 french window':'336','Canvas sidewall c/w 2 french window':'338','Canvas sidewall c/w 3 side liner (CM)':'340','Hard Panel Sidewall complete set':'342','Glass panel sidewall complete set':'344'},
  ufCrmQuoteGableEndCanvas: {'1 pcs':'346','2 pcs':'348','No':'350'},
  ufCrmQuoteGableEndCanvasDetails: {'Std Cutting':'352','Printing Cutting':'354','C/W Window':'356','C/W Tensioning Cable':'358','C/W Tensioning Complete Set (tension tubes & patches)':'360','C/W Tensioning Complete Set (tension tubes & J-Tension Rod)':'362'},
  ufCrmQuoteGableEndStructure: {'1 Set':'364','2 Set':'366','No':'368'},
  ufCrmQuoteGutter: {'Canvas Gutter c/w wall hook':'370','PVC Gutter c/w hook bracke':'372','Zinc Gutter c/w pvc down pipe (CM)':'374','No':'376'},
  ufCrmQuoteDoor: {'Double Door':'378','Single Door':'380','Super Double Door':'382','Super Single Door':'384','Roller Shutter':'386','Industrial Sliding Door':'388','Motorize Shutter Door':'390'},
  ufCrmQuoteAccessories: {'Roof Underlay':'392','Gable End Underlay':'394','Sidewall Underlay':'396','Alumunium Foil':'398','50 Inch Industrial Ventilation Fan c/w Frame':'400','Highbay LED c/w Wiring':'402'}
};

// Fuzzy enum lookup — case-insensitive + normalized whitespace/punctuation
function lookupEnumId(fieldName, value) {
  if (!value) return null;
  const options = ENUM_MAP[fieldName];
  if (!options) return null;
  const val = String(value).trim();
  if (options[val]) return options[val];
  const lower = val.toLowerCase();
  for (const [k, v] of Object.entries(options)) {
    if (k.toLowerCase() === lower) return v;
  }
  const norm = s => s.toLowerCase().replace(/[\s\-\_\.]/g, '').replace(/\/w/g, 'w');
  const target = norm(val);
  for (const [k, v] of Object.entries(options)) {
    if (norm(k) === target) return v;
  }
  return null;
}

async function bx(method, body) {
  const r = await this.helpers.httpRequest({
    method: 'POST', url: `${BASE}/${method}`,
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify(body || {}), json: false
  });
  return typeof r === 'string' ? JSON.parse(r) : r;
}

// Parse AI response
const resp = $input.first().json;
const raw = resp.choices?.[0]?.message?.content;
if (!raw) throw new Error('OpenAI returned no content');
let data;
try { data = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch (e) { throw new Error('AI JSON parse failed: ' + String(raw).slice(0, 300)); }
const origItemId = $('Detect Format').first().json.itemId;
const quotations = data.quotations || (data.line_items ? [{ quotation_ref: data.quotation_ref, quotation_date: data.quotation_date, grand_total_rm: data.grand_total_rm, line_items: data.line_items }] : []);
if (quotations.length === 0) throw new Error('AI returned no quotations');

// Flatten to line items
const allLines = [];
quotations.forEach((q, qIdx) => {
  (q.line_items || []).forEach((li, lIdx) => {
    allLines.push({ qIdx, lIdx, quotation: q, line: li });
  });
});
if (allLines.length === 0) throw new Error('No line items after flattening');

// Idempotency: delete existing child Quotes from previous runs (same origItemId reference in title, or same quotationRef).
// We identify children by title containing the origItemId's quotationRef. If original quote already has a ufCrmQuoteQref (from prior run), delete siblings sharing that ref.
const origItem = $('Bitrix: Get Quote').first().json.result?.item || {};
const existingRef = origItem.ufCrmQuoteQref;
if (existingRef) {
  const siblings = await bx.call(this, 'crm.item.list', { entityTypeId: QUOTE_ENTITY_TYPE_ID, filter: { ufCrmQuoteQref: existingRef }, select: ['id'] });
  const sibItems = siblings.result?.items || [];
  for (const s of sibItems) {
    if (s.id != origItemId) {
      await bx.call(this, 'crm.item.delete', { entityTypeId: QUOTE_ENTITY_TYPE_ID, id: s.id });
    }
  }
}

const results = [];

for (let idx = 0; idx < allLines.length; idx++) {
  const { qIdx, lIdx, quotation, line } = allLines[idx];
  const isFirstOverall = idx === 0;
  const productFamily = String(line.product_family || line.product || 'Unnamed').trim().slice(0, 250);
  const productVariantName = String(line.product_variant_name || line.product || 'Unnamed Variant').trim().slice(0, 250);
  const specs = line.specs || {};
  const quantity = line.quantity || 1;
  const unitPrice = line.unit_price_rm || 0;
  const lineTotal = line.line_total_rm || unitPrice * quantity;
  const quotationRef = quotation.quotation_ref || '';
  const quotationDate = quotation.quotation_date || null;
  const grandTotal = quotation.grand_total_rm || 0;

  // 1. Find/create parent product (catalog iblock 14)
  let parentId;
  const parentFind = await bx.call(this, 'catalog.product.list', {
    select: ['id','name','iblockId'],
    filter: { iblockId: 14, '=name': productFamily }
  });
  const parentMatches = parentFind.result?.products || [];
  if (parentMatches.length > 0) {
    parentId = parentMatches[0].id;
  } else {
    const parentAdd = await bx.call(this, 'catalog.product.add', { fields: { iblockId: 14, name: productFamily, active: 'Y' } });
    parentId = parentAdd.result?.element?.id;
    if (!parentId) throw new Error('Parent create failed: ' + JSON.stringify(parentAdd));
  }

  // 2. Find/create SKU offer (catalog iblock 16)
  let skuId;
  const skuFind = await bx.call(this, 'catalog.product.list', {
    select: ['id','name','iblockId'],
    filter: { iblockId: 16, '=name': productVariantName }
  });
  const skuMatches = skuFind.result?.products || [];
  if (skuMatches.length > 0) {
    skuId = skuMatches[0].id;
  } else {
    const skuFields = { iblockId: 16, name: productVariantName, active: 'Y', [`property${PROP_PARENT_LINK}`]: { value: parentId } };
    const specMap = {
      WIDTH: specs.width, LENGTH: specs.length, FRAME: specs.frame, PROFILE: specs.profile,
      CANVAS_MATERIAL: specs.canvas_material, COLOUR: specs.colour, STRUCTURE: specs.structure,
      CORNER_TYPE: specs.corner_type, SIDE_SUPPORT_TYPE: specs.side_support_type,
      QTY_SIDE_SUPPORT: specs.qty_side_support, GROUND_ANCHORING: specs.ground_anchoring,
      ROOF_CANVAS: specs.roof_canvas, SIDEWALL: specs.sidewall, SIDEWALL_OPTION: specs.sidewall_option,
      GABLE_END_CANVAS: specs.gable_end_canvas, GABLE_END_CANVAS_DETAILS: specs.gable_end_canvas_details,
      GABLE_END_STRUCTURE: specs.gable_end_structure, GUTTER: specs.gutter, DOOR: specs.door,
      DOOR_QTY: specs.door_qty, ACCESSORIES: specs.accessories, QUOTATION_REF: quotationRef
    };
    for (const [k, v] of Object.entries(specMap)) {
      if (v && String(v).trim()) skuFields[`property${PROP_CATALOG[k]}`] = { value: String(v) };
    }
    const skuAdd = await bx.call(this, 'catalog.product.add', { fields: skuFields });
    skuId = skuAdd.result?.element?.id;
    if (!skuId) throw new Error('SKU create failed: ' + JSON.stringify(skuAdd));
  }

  // 3. Build Quote fields with enum mapping
  const quoteFields = {
    ufCrmQuoteQref: quotationRef,
    ufCrmQuoteQuotationDate: quotationDate,
    ufCrmQuoteGrandTotalRm: grandTotal,
    ufCrmQuoteLineItemNo: line.line_no || (lIdx + 1),
    ufCrmQuoteProduct: productVariantName,
    ufCrmQuoteUnitPrice: unitPrice,
    ufCrmQuoteLineTotalRm: lineTotal,
    ufCrmQuoteFrame: specs.frame || '',
    ufCrmQuoteDoorQty: parseInt(specs.door_qty) || 0
  };
  // Enum fields — map string → enum ID
  const enumFieldMap = {
    ufCrmQuoteWidth: specs.width,
    ufCrmQuoteLength: specs.length,
    ufCrmQuoteProfile: specs.profile,
    ufCrmQuoteCanvasMaterial: specs.canvas_material,
    ufCrmQuoteColour: specs.colour,
    ufCrmQuoteStructure: specs.structure,
    ufCrmQuoteCornerType: specs.corner_type,
    ufCrmQuoteSideSupportType: specs.side_support_type,
    ufCrmQuoteQtySideSupports: specs.qty_side_support,
    ufCrmQuoteGroundAchoring: specs.ground_anchoring,
    ufCrmQuoteRoofCanvas: specs.roof_canvas,
    ufCrmQuoteSidewall: specs.sidewall,
    ufCrmQuoteSidewallOption: specs.sidewall_option,
    ufCrmQuoteGableEndCanvas: specs.gable_end_canvas,
    ufCrmQuoteGableEndCanvasDetails: specs.gable_end_canvas_details,
    ufCrmQuoteGableEndStructure: specs.gable_end_structure,
    ufCrmQuoteGutter: specs.gutter,
    ufCrmQuoteDoor: specs.door,
    ufCrmQuoteAccessories: specs.accessories
  };
  for (const [fieldName, value] of Object.entries(enumFieldMap)) {
    const enumId = lookupEnumId(fieldName, value);
    if (enumId) quoteFields[fieldName] = enumId;
  }

  // 4. Update or create Quote
  let quoteId;
  const quoteTitle = quotationRef
    ? `${quotationRef} — ${productFamily}${allLines.length > 1 ? ` (Line ${line.line_no || (lIdx+1)})` : ''}`
    : productVariantName;
  if (isFirstOverall) {
    // Update original quote — first line of first quotation reuses the SPA/Quote user attached file to
    const updResp = await bx.call(this, 'crm.item.update', { entityTypeId: QUOTE_ENTITY_TYPE_ID, id: origItemId, fields: { ...quoteFields, title: quoteTitle } });
    quoteId = updResp.result?.item?.id || origItemId;
  } else {
    const addResp = await bx.call(this, 'crm.item.add', { entityTypeId: QUOTE_ENTITY_TYPE_ID, fields: { ...quoteFields, title: quoteTitle } });
    quoteId = addResp.result?.item?.id;
    if (!quoteId) throw new Error('Quote add failed: ' + JSON.stringify(addResp));
  }

  // 5. Set product row on this Quote (atomic replace — no dup on re-fire)
  await bx.call(this, 'crm.quote.productrows.set', {
    id: quoteId,
    rows: [{ PRODUCT_ID: skuId, PRICE: unitPrice, QUANTITY: quantity }]
  });

  results.push({ json: { idx, qIdx, lIdx, quoteId, parentId, skuId, productFamily, productVariantName, unitPrice, quantity, quotationRef } });
}
return results;

